let Interrupts = dynamic(["50058", "50140", "51006", "50059", "65001", "52004", "50055", "50144", "50072", "50074",
                          "16000", "16001", "16003", "50127", "50125", "50129", "50143", "81010", "81014", "81012"]);
SigninLogs
| extend Outcome = case(ResultType == "0", "Success", ResultType in (Interrupts), "Interrupted", "Failure")
| summarize SignIns = count() by bin(TimeGenerated, {TimeRange:grain}), Outcome

let Interrupts = dynamic(["50058", "50140", "51006", "50059", "65001", "52004", "50055", "50144", "50072", "50074",
                          "16000", "16001", "16003", "50127", "50125", "50129", "50143", "81010", "81014", "81012"]);
SigninLogs
| where ResultType != "0" and ResultType !in (Interrupts)
| summarize Failures = count() by Country = iff(isempty(Location), "Unknown", Location)
| top 15 by Failures desc
